pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address other, uint256 amount) internal {
        vm.assume(amount > 0);
        vm.assume(other != address(this));
        uint balBefore = address(c).balance;
        uint256 myRecorded;
        try c.balances(address(this)) returns (uint256 __r) { myRecorded = __r; } catch { return; }
        uint256 otherRecorded;
        try c.balances(other) returns (uint256 __r) { otherRecorded = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false && address(c).balance == balBefore && c.balances(address(this)) == myRecorded && c.balances(other) == otherRecorded);
    }

    function testFuzz_run(address other, uint256 amount) public {
